corrected_code:
const express = require('express');
const { Sequelize, QueryTypes } = require('sequelize');

const app = express();
const sequelize = new Sequelize(process.env.HEALTH_DB_URI);

app.get('/api/patients/:patientId/clinical-notes', async (req, res) => {
  const { patientId } = req.params;

  // Enforce clinic isolation and verify practitioner assignment
  try {
    const notes = await sequelize.query(
      `SELECT cn.id, cn.note_text, cn.diagnosis_code, cn.created_at, d.full_name as practitioner_name
       FROM clinical_notes cn
       JOIN practitioners d ON cn.practitioner_id = d.id
       WHERE cn.patient_id = :patientId AND cn.clinic_id = :clinicId
       ORDER BY cn.created_at DESC`,
      {
        replacements: { patientId, clinicId: req.user.clinicId },
        type: QueryTypes.SELECT
      }
    );

    return res.json({ patientId, notes });
  } catch (err) {
    return res.status(500).json({ error: 'Failed to retrieve clinical notes' });
  }
});

module.exports = app;
